def seed_categories(apps, schema_editor):
    """Registra las categorías ya usadas por cada usuario, sin tocar las tareas."""
    TodoTask = apps.get_model("todos", "TodoTask")
    Category = apps.get_model("todos", "Category")

    seen = set()
    for task in TodoTask.objects.order_by("id").only("user_id", "category").iterator():
        name = " ".join((task.category or "").split())[:50]
        if not name:
            continue

        normalized = name.casefold()
        key = (task.user_id, normalized)
        if key in seen:
            continue
        seen.add(key)

        Category.objects.get_or_create(
            user_id=task.user_id,
            normalized_name=normalized,
            defaults={"name": name},
        )


def remove_seeded_categories(apps, schema_editor):
    """Revierte solo el registro de categorías; las tareas permanecen intactas."""
    apps.get_model("todos", "Category").objects.all().delete()


